ation_modern_name": null, "location_note": null, "status": "draft", "id": "637a0b07-cf05-5d98-878d-f4fba3841540"}, {"title": "宫中宦官在云南采买珍宝", "description": "天顺二年二月，本纪记宫中的宦官在云南采买珍宝。", "start_year": 1458, "end_year": 1458, "time_original": "天顺二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b798074-a4fa-5e21-be4d-65fded6f0a43"}, {"title": "明廷安葬土木遗留的骸骨", "description": "天顺二年闰二月己卯，明廷收殓并安葬暴露在土木的遗骸。", "start_year": 1458, "end_year": 1458, "time_original": "天顺二年闰二月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "611b72a7-a82b-58ae-9a14-bf653d5ec775"}, {"title": "明廷恢复设置巡抚官", "description": "天顺二年四月，明廷恢复设置巡抚官。", "start_year": 1458, "end_year": 1458, "time_original": "天顺二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f8fcee61-e904-56b3-a59e-104e9dea176a"}, {"title": "明廷授吴与弼左谕德，吴与弼辞谢", "description": "天顺二年五月壬寅，朝廷授予处士吴与弼左谕德官职。吴与弼辞谢，没有就任，随后朝廷送他回乡。", "start_year": 1458, "end_year": 1458, "time_original": "天顺二年五月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b91c8ba8-1e86-5c81-a4dc-18253158e66f"}, {"title": "石彪任总兵官，赴宁夏抵御来犯军队", "description": "天顺二年七月癸卯，明廷任命定远伯石彪为平夷将军、总兵官，派他到宁夏抵御来犯军队。", "start_year": 1458, "end_year": 1458, "time_original": "天顺二年七月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b68457c-c68f-5ae9-bbb7-2829c581c75b"}, {